<?php
if(!defined('ABSPATH'))exit;
function dgs_manage_allowed(){return current_user_can('dgs_manage_education');}
function dgs_manage_flash_redirect($result,$tab,$year,$args=array()){$token=wp_generate_password(24,false,false);set_transient('dgs_edu_flash_'.get_current_user_id().'_'.$token,array('error'=>is_wp_error($result),'text'=>is_wp_error($result)?$result->get_error_message():$result),300);wp_safe_redirect(dgs_school_url($tab,$year,array_merge($args,array('dg_notice'=>$token))),303);exit;}
function dgs_request_states(){return array('new'=>'در انتظار بررسی','review'=>'در حال بررسی','referred'=>'در حال پیگیری','approved'=>'تأیید شده','rejected'=>'رد شده','closed'=>'بسته شده');}
function dgs_request_private($id){$p=get_post(absint($id));return dgs_manage_allowed()&&$p&&$p->post_type==='dgs_request'&&$p->post_status==='private'?$p:null;}
function dgs_request_review_hash($id){return wp_hash(wp_json_encode(array(get_post_meta($id,'_dgs_status',true),get_post_meta($id,'_dgs_staff_note',true),get_post_meta($id,'_dgs_review',true))));}
function dgs_request_review_save($d){if(!dgs_manage_allowed())return dgs_edu_error('access','دسترسی مجاز نیست.');foreach($d as $v)if(!is_scalar($v))return dgs_edu_error('input','درخواست معتبر نیست.');$id=absint($d['request_id']??0);$status=(string)($d['status']??'');$note=sanitize_textarea_field((string)($d['note']??''));if(!dgs_request_private($id)||!isset(dgs_request_states()[$status])||dgs_edu_length($note)>4000)return dgs_edu_error('input','درخواست، وضعیت یا یادداشت معتبر نیست.');if(!hash_equals(dgs_request_review_hash($id),(string)($d['revision']??'')))return dgs_edu_error('stale','درخواست تغییر کرده است؛ صفحه را تازه کنید.');if($status==='rejected'&&$note==='')return dgs_edu_error('reason','دلیل رد را در یادداشت بنویسید.');$old=get_post_meta($id,'_dgs_review',true);$next=array('revision'=>(is_array($old)?(int)($old['revision']??0):0)+1,'by'=>get_current_user_id(),'at'=>current_time('mysql'),'status'=>$status,'note'=>$note);global $wpdb;$wpdb->query('START TRANSACTION');$ok=$old?update_post_meta($id,'_dgs_review',$next,$old):add_post_meta($id,'_dgs_review',$next,true);if($ok){$before=get_post_meta($id,'_dgs_status',true);$previous_note=get_post_meta($id,'_dgs_staff_note',true);if($before!==$status&&!update_post_meta($id,'_dgs_status',$status))$ok=false;if($previous_note!==$note&&!update_post_meta($id,'_dgs_staff_note',$note))$ok=false;}if(!$ok){$wpdb->query('ROLLBACK');wp_cache_delete($id,'post_meta');return dgs_edu_error('write','ثبت کامل نشد؛ صفحه را تازه کنید.');}$wpdb->query('COMMIT');dgs_edu_audit('request_review',$id);return 'وضعیت و یادداشت درخواست ذخیره شد؛ حساب دانش‌آموز خودکار ساخته نشد.';}
function dgs_request_files_cleanup($files){foreach($files as $f)if(preg_match('/^[a-f0-9]{32}\.(pdf|png|jpe?g)$/D',$f['stored_file']??''))@unlink(dgs_hw_dir().'/'.$f['stored_file']);}
function dgs_request_uploads($raw,$store=false){if(!$raw||($raw['error']??null)===UPLOAD_ERR_NO_FILE)return $store?array():'';if(!is_array($raw)||!isset($raw['name'],$raw['tmp_name'],$raw['size'],$raw['error'])||!is_array($raw['name'])||count($raw['name'])>5)return dgs_edu_error('files','حداکثر پنج مدرک بارگذاری کنید.');$files=array();$sum=0;foreach($raw['name'] as $i=>$name){$err=$raw['error'][$i]??UPLOAD_ERR_NO_FILE;if($err===UPLOAD_ERR_NO_FILE)continue;$tmp=$raw['tmp_name'][$i]??'';$size=$raw['size'][$i]??0;if(!is_string($name)||!is_string($tmp)||!is_scalar($size)||$err!==UPLOAD_ERR_OK||!is_uploaded_file($tmp)||$size<1||$size>10*1024*1024||!in_array(strtolower(pathinfo($name,PATHINFO_EXTENSION)),array('pdf','png','jpg','jpeg'),true))return dgs_edu_error('file','هر مدرک PDF/JPG/PNG سالم و حداکثر ۱۰ مگابایت باشد.');$sum+=(int)$size;if($sum>20*1024*1024)return dgs_edu_error('file','مجموع مدارک حداکثر ۲۰ مگابایت باشد.');$files[]=array('name'=>$name,'tmp_name'=>$tmp,'size'=>(int)$size,'error'=>UPLOAD_ERR_OK,'slot'=>(string)$i);}
 if(!$store){$parts=array();foreach($files as $f)$parts[]=hash_file('sha256',$f['tmp_name']);return implode('|',$parts);}$stored=array();foreach($files as $file){$f=dgs_hw_store($file);if(is_wp_error($f)){dgs_request_files_cleanup($stored);return $f;}$f['token']=wp_generate_uuid4();$f['document_kind']=$file['slot'];$stored[]=$f;}return $stored;
}
function dgs_request_file($id,$token){if(!dgs_request_private($id)||!is_string($token))return null;$files=get_post_meta($id,'_dgs_request_files',true);if(!is_array($files))return null;foreach($files as $f)if(is_array($f)&&($f['token']??'')===$token)return $f;return null;}
add_action('admin_post_dgs_request_file',function(){$id=absint($_GET['request_id']??0);if(!dgs_request_private($id))wp_die('دسترسی مجاز نیست.','',array('response'=>403));check_admin_referer('dgs_request_file');$f=dgs_request_file($id,$_GET['file']??'');if(!$f||!preg_match('/^[a-f0-9]{32}\.(pdf|png|jpe?g)$/D',$f['stored_file']))wp_die('مدرک پیدا نشد.','',array('response'=>404));$path=dgs_hw_dir().'/'.$f['stored_file'];if(!is_file($path))wp_die('مدرک پیدا نشد.','',array('response'=>404));nocache_headers();header('Cache-Control: private, no-store');header('X-Content-Type-Options: nosniff');header('Content-Type: '.$f['file_mime']);header('Content-Disposition: attachment; filename="document.'.pathinfo($path,PATHINFO_EXTENSION).'"');header('Content-Length: '.filesize($path));while(ob_get_level())ob_end_clean();readfile($path);exit;});
function dgs_request_query($type,$status='',$from='',$to='',$page=1){if(!dgs_manage_allowed())return null;$meta=array(array('key'=>'_dgs_data','value'=>'s:4:"type";'.serialize($type),'compare'=>'LIKE'));if(isset(dgs_request_states()[$status]))$meta[]=array('key'=>'_dgs_status','value'=>$status);$args=array('post_type'=>'dgs_request','post_status'=>'private','posts_per_page'=>10,'paged'=>max(1,$page),'orderby'=>'ID','order'=>'DESC','meta_query'=>$meta);$date=array('inclusive'=>true);if($from)$date['after']=$from.' 00:00:00';if($to)$date['before']=$to.' 23:59:59';if(count($date)>1)$args['date_query']=array($date);return new WP_Query($args);}
function dgs_os_context($d,$year){$fallback=substr(dgs_att_jdate(dgs_att_today()),0,7);$month=dgs_grade_period(is_scalar($d['os_month']??null)?(string)$d['os_month']:'',$year)?: (dgs_grade_period($fallback,$year)?:substr($year,0,4).'-07');$assessment=is_scalar($d['os_assessment']??null)?(string)$d['os_assessment']:'month';if(!in_array($assessment,array('month','term1','term2'),true))$assessment='month';$periods=array($month);if($assessment!=='month'){$periods=array();foreach($assessment==='term1'?array(7,8,9,10):array(11,12,1,2,3,4,5,6) as $m)$periods[]=sprintf('%04d-%02d',(int)substr($year,$m>=7?0:5,4),$m);}return array('year'=>$year,'month'=>$month,'assessment'=>$assessment,'periods'=>$periods,'class'=>is_scalar($d['os_class']??null)?absint($d['os_class']):0,'grade'=>is_scalar($d['os_grade']??null)?absint($d['os_grade']):0,'field'=>is_scalar($d['os_field']??null)?sanitize_key($d['os_field']):'');}
function dgs_os_data($ctx){if(!dgs_manage_allowed())return null;global $wpdb;$e=dgs_edu_tables();$g=dgs_grade_table();$classes=array();foreach(dgs_edu_classes($ctx['year']) as $c)if(!$ctx['class']||(int)$c->id===$ctx['class'])$classes[$c->id]=$c;$pairs=array();$students=array();$records=array();if($classes){$ids=implode(',',array_map('intval',array_keys($classes)));$pairs=$wpdb->get_results("SELECT a.*,s.title AS subject,u.display_name AS teacher FROM {$e['teaching']} a JOIN {$e['subjects']} s ON s.id=a.subject_id JOIN {$wpdb->users} u ON u.ID=a.teacher_id WHERE a.class_id IN ($ids) AND s.active=1 ORDER BY u.display_name,a.id");$students=$wpdb->get_results("SELECT en.student_id,en.class_id,u.display_name FROM {$e['enrollments']} en JOIN {$wpdb->users} u ON u.ID=en.student_id WHERE en.class_id IN ($ids) ORDER BY u.display_name,u.ID");$marks=implode(',',array_fill(0,count($ctx['periods']),'%s'));$records=$wpdb->get_results($wpdb->prepare("SELECT g.* FROM $g g WHERE g.class_id IN ($ids) AND g.period IN ($marks) ORDER BY g.id",$ctx['periods']));}
 $states=array();if(function_exists('dgs_mg_tables')&&$classes){$mt=dgs_mg_tables();foreach($wpdb->get_results("SELECT class_id,subject_id,period,status FROM {$mt['states']} WHERE class_id IN ($ids)") as $st)$states[$st->class_id.':'.$st->subject_id.':'.$st->period]=$st->status;}
 $index=array();foreach($records as $r)$index[$r->class_id.':'.$r->student_id.':'.$r->subject_id.':'.$r->period]=$r;$expected=array();$teachers=array();$by_class=array();foreach($pairs as $p){$by_class[$p->class_id]=true;$key=$p->teacher_id.':'.$p->subject_id;if(!isset($teachers[$key]))$teachers[$key]=array('name'=>$p->teacher,'subject'=>$p->subject,'grades'=>array(),'expected'=>0,'done'=>0);$teachers[$key]['grades'][$classes[$p->class_id]->grade]=true;foreach($students as $s)if((int)$s->class_id===(int)$p->class_id)foreach($ctx['periods'] as $period){$id=$p->class_id.':'.$s->student_id.':'.$p->subject_id.':'.$period;$expected[$id]=$index[$id]??null;$teachers[$key]['expected']++;if(isset($index[$id])&&(($states[$p->class_id.':'.$p->subject_id.':'.$period]??'legacy')!=='open'))$teachers[$key]['done']++;}}
 $unconfigured=0;foreach($students as $s)if(!isset($by_class[$s->class_id]))$unconfigured++;$valid=array_filter($expected);$averages=array();foreach($students as $s)$averages[$s->student_id]=array('id'=>$s->student_id,'name'=>$s->display_name,'class_id'=>$s->class_id,'grade'=>$classes[$s->class_id]->grade,'field'=>$classes[$s->class_id]->field,'sum'=>0,'count'=>0);foreach($valid as $r){$averages[$r->student_id]['sum']+=(float)$r->score;$averages[$r->student_id]['count']++;}foreach($averages as &$s)$s['average']=$s['count']?$s['sum']/$s['count']:null;unset($s);$digest=array($ctx['year'],$ctx['periods'],array_keys($classes),array_keys($expected),$unconfigured);foreach($valid as $r)$digest[]=array($r->id,$r->score,$r->published,$r->updated_at,$r->class_id);return array('classes'=>$classes,'pairs'=>$pairs,'students'=>$students,'records'=>$valid,'expected'=>count($expected),'missing'=>count($expected)-count($valid),'unconfigured'=>$unconfigured,'teachers'=>$teachers,'averages'=>$averages,'hash'=>wp_hash(wp_json_encode($digest)));}
function dgs_os_grade_hash($r){return wp_hash(wp_json_encode(array($r->id,$r->score,$r->published,$r->updated_at,$r->class_id,$r->period)));}
function dgs_os_publish($d,$ctx){if(function_exists('dgs_mg_publish'))return dgs_mg_publish($d,$ctx);if(!dgs_manage_allowed())return dgs_edu_error('access','انتشار فقط برای مدیر و معاون است.');if(($d['approve']??'')!=='1')return dgs_edu_error('approve','پیش‌نمایش را بررسی و تأیید انتشار را علامت بزنید.');$data=dgs_os_data($ctx);if(!$data['expected']||$data['missing']||$data['unconfigured'])return dgs_edu_error('missing','نمرات یا تخصیص درس‌ها کامل نیست؛ انتشار متوقف شد.');if(!is_string($d['snapshot']??null)||!hash_equals($data['hash'],$d['snapshot']))return dgs_edu_error('stale','اطلاعات پس از پیش‌نمایش تغییر کرده است؛ گزارش را تازه کنید.');global $wpdb;$g=dgs_grade_table();$wpdb->query('START TRANSACTION');foreach($data['records'] as $r){$ok=$wpdb->query($wpdb->prepare("UPDATE $g SET published=1 WHERE id=%d AND score=%s AND updated_at=%s AND published=%d AND class_id=%d",$r->id,$r->score,$r->updated_at,$r->published,$r->class_id));if($ok===0&&(int)$r->published){$now=$wpdb->get_row($wpdb->prepare("SELECT score,published,updated_at,class_id FROM $g WHERE id=%d",$r->id));if(!$now||(float)$now->score!==(float)$r->score||!(int)$now->published||$now->updated_at!==$r->updated_at||(int)$now->class_id!==(int)$r->class_id)$ok=false;}if($ok===false||(!$ok&&!(int)$r->published)){$wpdb->query('ROLLBACK');return dgs_edu_error('stale','انتشار کامل نشد؛ نمرات تغییر کرده‌اند.');}}$wpdb->query('COMMIT');dgs_edu_audit('oversight_publish',count($data['records']));return 'نمرات بازه انتخابی منتشر شد و در کارنامه‌های ماهانه دانش‌آموز قابل مشاهده است.';}
function dgs_os_edit($d,$ctx){if(function_exists('dgs_mg_write'))return dgs_edu_error('ledger','اصلاح نمره از دفتر ثبت نمرات، با انتخاب ماه و ثبت دلیل انجام می‌شود.');if(!dgs_manage_allowed())return dgs_edu_error('access','دسترسی مجاز نیست.');$scores=$d['os_scores']??null;$hashes=$d['os_hashes']??null;if(!is_array($scores)||!is_array($hashes)||!$scores||count($scores)>100)return dgs_edu_error('scores','فهرست معتبر تا ۱۰۰ نمره لازم است.');$data=dgs_os_data($ctx);$allowed=array();foreach($data['records'] as $r)$allowed[$r->id]=$r;$changes=array();foreach($scores as $id=>$raw){if(!ctype_digit((string)$id)||!isset($allowed[$id])||!is_scalar($raw)||!is_string($hashes[$id]??null)||!hash_equals(dgs_os_grade_hash($allowed[$id]),$hashes[$id]))return dgs_edu_error('stale','نمره خارج از محدوده است یا تغییر کرده؛ صفحه را تازه کنید.');$score=str_replace(array('٫','/'),'.',dgs_edu_digits((string)$raw));if(!preg_match('/^\d{1,2}(\.\d{1,2})?$/D',$score)||(float)$score>20)return dgs_edu_error('score','نمره بین صفر تا ۲۰ و حداکثر دو رقم اعشار باشد.');if((float)$score!==(float)$allowed[$id]->score)$changes[]=array($allowed[$id],$score);}if(!$changes)return 'نمره‌ای تغییر نکرد.';global $wpdb;$g=dgs_grade_table();$wpdb->query('START TRANSACTION');foreach($changes as $entry){list($r,$score)=$entry;$ok=$wpdb->query($wpdb->prepare("UPDATE $g SET score=%s,published=0,updated_at=%s,updated_by=%d WHERE id=%d AND score=%s AND published=%d AND updated_at=%s",$score,current_time('mysql'),get_current_user_id(),$r->id,$r->score,$r->published,$r->updated_at));if($ok!==1){$wpdb->query('ROLLBACK');return dgs_edu_error('write','ذخیره متوقف شد؛ نمره هم‌زمان تغییر کرده است.');}}$wpdb->query('COMMIT');dgs_edu_audit('oversight_edit',count($changes));return 'تغییرات ذخیره شد؛ نمرات اصلاح‌شده برای تأیید دوباره پیش‌نویس شدند.';}
add_action('admin_post_dgs_management',function(){if(($_SERVER['REQUEST_METHOD']??'')!=='POST'||!dgs_manage_allowed())wp_die('دسترسی مجاز نیست.','',array('response'=>403));check_admin_referer('dgs_management','dgs_management_nonce');$d=wp_unslash($_POST);$year=is_string($d['year']??null)?dgs_edu_year($d['year']):'';if(!$year)wp_die('سال معتبر نیست.','',array('response'=>400));$op=is_string($d['operation']??null)?$d['operation']:'';if($op==='request_review'){$r=dgs_request_review_save($d);dgs_manage_flash_redirect($r,'requests',$year,array('request_id'=>absint($d['request_id']??0),'rq_type'=>is_string($d['rq_type']??null)?sanitize_key($d['rq_type']):'admission'));}$ctx=dgs_os_context($d,$year);$r=$op==='publish'?dgs_os_publish($d,$ctx):($op==='edit_grades'?dgs_os_edit($d,$ctx):dgs_edu_error('op','عملیات معتبر نیست.'));dgs_manage_flash_redirect($r,'oversight',$year,array('os_month'=>$ctx['month'],'os_assessment'=>$ctx['assessment'],'os_class'=>$ctx['class'],'os_pair'=>is_string($d['os_pair']??null)&&preg_match('/^\d+:\d+$/D',$d['os_pair'])?$d['os_pair']:''));});
add_action('admin_post_dgs_oversight_export',function(){if(!dgs_manage_allowed())wp_die('دسترسی مجاز نیست.','',array('response'=>403));check_admin_referer('dgs_oversight_export');$year=dgs_edu_year(dgs_att_get('year'));if(!$year)wp_die('سال معتبر نیست.');$ctx=dgs_os_context($_GET,$year);$data=dgs_os_data($ctx);$e=dgs_edu_tables();global $wpdb;$subjects=array();foreach(dgs_edu_subjects() as $s)$subjects[$s->id]=$s->title;$rows=array(array('دانش‌آموز','کلاس','درس','ماه','نمره از ۲۰','وضعیت'));foreach($data['records'] as $r){if(count($rows)>5000)wp_die('محدوده را کوچک‌تر کنید؛ خروجی تا ۵۰۰۰ نمره است.');$rows[]=array($data['averages'][$r->student_id]['name'],dgs_edu_class_label($data['classes'][$r->class_id]),$subjects[$r->subject_id]??'',$r->period,$r->score,$r->published?'منتشرشده':'پیش‌نویس');}$bytes=dgs_school_xlsx($rows);if(is_wp_error($bytes))wp_die(esc_html($bytes->get_error_message()));nocache_headers();header('Content-Type: application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');header('Content-Disposition: attachment; filename="daneshgaran-grades-'.$year.'.xlsx"');header('Content-Length: '.strlen($bytes));echo $bytes;exit;});
